import networkx as nx
import itertools
import random

def get_max_f(edges, v=15, j_size=8):
    max_edges = 0
    for J in itertools.combinations(range(v), j_size):
        count = 0
        for u, v_edge in edges:
            if u in J and v_edge in J:
                count += 1
        if count > max_edges:
            max_edges = count
    return max_edges

best_max = 100
for _ in range(100):
    G = nx.random_regular_graph(8, 15)
    edges = list(G.edges())
    random.shuffle(edges)
    edges = edges[:56]
    current_max = get_max_f(edges)
    if current_max < best_max:
        best_max = current_max
print(best_max)

import networkx as nx
import itertools
import random

def get_min_f_bar(edges, v=15, j_size=8):
    min_edges = 100
    for J in itertools.combinations(range(v), j_size):
        count = 0
        for u, v_edge in edges:
            if u in J and v_edge in J:
                count += 1
        if count < min_edges:
            min_edges = count
    return min_edges

best_min_f_bar = 0
for _ in range(200):
    G_bar = nx.random_regular_graph(8, 15)
    edges = list(G_bar.edges())
    random.shuffle(edges)
    edges = edges[11:] # Remove 11 edges to get 49
    current_min = get_min_f_bar(edges)
    if current_min > best_min_f_bar:
        best_min_f_bar = current_min
print(best_min_f_bar)
